// Obtiene todos los items de entrada
const items = $input.all();

// Arma un texto con todas las memorias incluyendo el id
const texto = items
  .map(item => `- id: ${item.json.id} | ${item.json.fields.clave}: ${item.json.fields.valor}`)
  .join("\n");

// Devuelve un único item
return [
  {
    json: {
      memoria: texto
    }
  }
];
